CREATE OR REPLACE FUNCTION public.capture_applicant_workday_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public AS $$ DECLARE v_name text := trim(coalesce(NEW.first_name,'') || ' ' || coalesce(NEW.last_name,'')); BEGIN IF NEW.is_test_row THEN RETURN NEW; END IF; IF TG_OP='INSERT' THEN INSERT INTO public.admin_workday_events(event_type,applicant_id,title,detail,status,action_label,action_url,waiting_on_admin,metadata) VALUES('candidate_added',NEW.id,'Candidate added — ' || coalesce(nullif(v_name,''),'Unnamed candidate'),'Recruitment source: ' || coalesce(NEW.source,'unconfirmed') || ' · Not submitted on Tidy','awaiting_application','Open candidate','/admin/pipeline/' || NEW.id,false,jsonb_build_object('source',NEW.source)); ELSIF NEW.current_stage IS DISTINCT FROM OLD.current_stage THEN INSERT INTO public.admin_workday_events(event_type,applicant_id,title,detail,status,action_label,action_url,waiting_on_admin,metadata) VALUES('stage_change',NEW.id,coalesce(nullif(v_name,''),'Candidate') || ' stage changed',coalesce(OLD.current_stage,'—') || ' → ' || coalesce(NEW.current_stage,'—'),NEW.current_stage,'Open candidate','/admin/pipeline/' || NEW.id,NEW.current_stage IN ('screening','interview','offer','bg_check','contracts','kit'),jsonb_build_object('from',OLD.current_stage,'to',NEW.current_stage)); END IF; IF TG_OP='UPDATE' AND NEW.bg_check_status IS DISTINCT FROM OLD.bg_check_status THEN INSERT INTO public.admin_workday_events(event_type,applicant_id,title,detail,status,action_label,action_url,waiting_on_admin,metadata) VALUES('background_check',NEW.id,'Background check — ' || v_name,coalesce(NEW.bg_check_status,'updated'),NEW.bg_check_status,'Open candidate','/admin/pipeline/' || NEW.id,NEW.bg_check_status IN ('consider','suspended'),'{}'); END IF; IF TG_OP='UPDATE' AND NEW.call_at IS DISTINCT FROM OLD.call_at AND NEW.call_at IS NOT NULL THEN INSERT INTO public.admin_workday_events(event_type,applicant_id,title,detail,status,action_label,action_url,waiting_on_admin,metadata) VALUES('call_booked',NEW.id,'Call booked — ' || v_name,NEW.call_at::text,'booked','Open candidate','/admin/pipeline/' || NEW.id,false,jsonb_build_object('call_at',NEW.call_at)); END IF; RETURN NEW; END $$;